 "content": "from collections import deque


def transform(grid):
    """Apply the rectangle symmetry indicated by the three external color markers."""
    g = [list(row) for row in grid]
    R, C = len(g), len(g[0])

    # The large, solid nonzero rectangle is one 4-connected component; the
    # three reference markers outside it are separate components.
    seen = set()
    components = []
    for r in range(R):
        for c in range(C):
            if g[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < R and 0 <= xx < C and g[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            components.append(comp)
    panel = max(components, key=len)
    r0 = min(r for r, c in panel); r1 = max(r for r, c in panel)
    c0 = min(c for r, c in panel); c1 = max(c for r, c in panel)
    a = [row[c0:c1+1] for row in g[r0:r1+1]]
    H, W = len(a), len(a[0])
    panel_set = set(panel)

    outside = [(g[r][c], r, c) for r in range(R) for c in range(C)
               if g[r][c] != 0 and (r, c) not in panel_set]
    # Reference constellation: three distinct colors, each placed at a corner
    # of its own bounding box.
    targets = {}
    if outside:
        rr = [r for v,r,c in outside]; cc = [c for v,r,c in outside]
        rmin, rmax, cmin, cmax = min(rr), max(rr), min(cc), max(cc)
        for v, r, c in outside:
            targets[v] = ('T' if r-rmin <= rmax-r else 'B',
                          'L' if c-cmin <= cmax-c else 'R')

    def role(r, c, h, w):
        return ('T' if r < h/2 else 'B', 'L' if c < w/2 else 'R')

    # Eight rectangle symmetries, mapping input coordinates to output coords.
    ops = [
        (lambda r,c: (r,c), H,W),
        (lambda r,c: (H-1-r,c), H,W),             # vertical flip
        (lambda r,c: (r,W-1-c), H,W),             # horizontal flip
        (lambda r,c: (H-1-r,W-1-c), H,W),         # half turn
        (lambda r,c: (c,r), W,H),                 # main diagonal
        (lambda r,c: (W-1-c,H-1-r), W,H),         # anti-diagonal
        (lambda r,c: (c,H-1-r), W,H),             # clockwise quarter turn
        (lambda r,c: (W-1-c,r), W,H),             # counterclockwise quarter turn
    ]
    marker_positions = {}
    for r in range(H):
        for c in range(W):
            v = a[r][c]
            if v in targets:
                marker_positions[v] = (r,c)

    best = None
    best_score = -1
    for fn, oh, ow in ops:
        score = 0
        for v, (r,c) in marker_positions.items():
            if v in targets:
                rr, cc = fn(r,c)
                score += role(rr,cc,oh,ow) == targets[v]
        if score > best_score:
            best, best_score = (fn, oh, ow), score
    fn, oh, ow = best
    out = [[0 for _ in range(ow)] for _ in range(oh)]
    for r in range(H):
        for c in range(W):
            rr, cc = fn(r,c)
            out[rr][cc] = a[r][c]
    return out
"
